import json,pathlib
p=pathlib.Path('inventory');j=json.load(open(p/'devices.json'))
profiles={
'S5':{'cpu':'MPC8247 PowerPC 603e; teardown reports 300 MHz','ram':'32 MiB (2 x 128 Mbit SDRAM)','flash':'32 MiB NAND plus boot ROM','network':'Atheros AR5008-3NG miniPCI; two 10/100 Ethernet PHYs','audio':'Five drivers; CS44800 digital amplifier controller; CS5341 line-input ADC','sources':['https://www.huxiu.com/article/39121.html','https://www.nxp.com/products/MPC8247'],'qualification':'Published teardown, not chip inspection of owned units; source incorrectly calls CPU 64-bit; use 32-bit PowerPC architecture.'},
'S3':{'cpu':'MPC8314VRADDA PowerPC, 266 MHz in teardown','ram':'64 MiB DDR2 in teardown; exact owned revision not independently matched','flash':'64 MiB NAND (512 Mbit component)','network':'10/100 Ethernet 78Q2123; three radio antennas','audio':'Two midrange drivers, tweeter, passive radiator; STA339BW digital audio amplifiers','sources':['https://www.ifixit.com/News/4299/sonos-play3-teardown'],'qualification':'Published teardown sample; not proof all S3 revisions have identical RAM.'},
'S1':{'cpu':'MPC8314 PowerPC, early Play:1 board','ram':'Unresolved exact capacity for owned revision','flash':'Unresolved exact capacity for owned revision','network':'Ethernet and wireless; exact radio chip unresolved','audio':'Separate woofer/tweeter DAC channels; TPA3116 amplifier; crossover required','sources':['https://www.instructables.com/Add-Bluetooth-to-Sonos-Play1/','https://github.com/trulyspinach/sonos-fenway'],'qualification':'Early-board research; live model S1 is not the same concept as software generation S1.'},
'S12':{'cpu':'Candidate later Play:1: MCIMX6X2EVN10AB, Cortex-A9 rated 1 GHz plus Cortex-M4 rated 227 MHz','ram':'Candidate 256 MiB DDR3 MT41K128M16JT','flash':'Candidate 256 MiB NAND W29N02GVSIAA','network':'Candidate Atheros AR9582 miniPCIe; 78Q2133 10/100 PHY','audio':'Candidate TPA3116D2 amplifier; woofer and tweeter; S5851A temperature sensor','sources':['https://www.52audio.com/archives/47378.html'],'qualification':'Later Play:1 teardown. S12-to-this-board mapping remains an inference; chip rating is not measured running clock.'},
'Sub':{'cpu':'MPC8314 candidate if Gen 1 Anvil; exact generation mapping unresolved','ram':'Exact capacity unresolved; Sonos says Gen 1/2 legacy S2 devices <=256 MB','flash':'Unresolved','network':'Ethernet/wireless; exact radio unresolved','audio':'Subwoofer; crossover, phase/delay and excursion protection required','sources':['https://github.com/trulyspinach/sonos-fenway','https://support.sonos.com/en-au/article/legacy-product-update'],'qualification':'Live model name Sub alone is insufficient to certify generation or memory.'},
'S9':{'cpu':'Unresolved exact SoC','ram':'<=256 MB manufacturer legacy-family bound; exact capacity unresolved','flash':'Unresolved','network':'See manufacturer guide; exact silicon unresolved','audio':'Playbar television audio path; exact DAC/amplifier parts unresolved','sources':['https://support.sonos.com/en-au/article/legacy-product-update','https://www.sonos.com/pdfs/productguides/en-us/sonos-user-guide.pdf'],'qualification':'No exact board-specific CPU/RAM source established in this pass.'},
'ZB100':{'cpu':'Unresolved','ram':'Unresolved','flash':'Unresolved','network':'Sonos network bridge','audio':'No audio outputs','sources':['https://www.ifixit.com/Device/Sonos_Bridge'],'qualification':'Network-only device; exclude from first audio firmware target.'}}
for r in j['devices']:r['published_hardware_profile']=profiles[r['fields']['modelNumber']]
(p/'devices.json').write_text(json.dumps(j,indent=2))
(p/'hardware-profiles.json').write_text(json.dumps(profiles,indent=2))
records=[]
for r in j['devices']:
 f=r['fields']; z=r['status']; profile=r['published_hardware_profile']
 content='Sonos inventory observed '+j['observed_at']+': '+json.dumps({'identity':{k:f.get(k) for k in ['serialNum','modelName','modelNumber','hardwareVersion','softwareVersion']},'room':z.get('ZoneName',f.get('roomName')),'location':r['url'],'software_generation':z.get('SWGen'),'published_hardware':profile})
 records.append({'content':content,'level':'semantic','kind':'fact','tags':['sonos','hardware-inventory',f['modelNumber'].lower()],'source':(p/'devices.json').resolve().as_uri(),'confidence':0.9})
(p/'ee-records.jsonl').write_text(''.join(json.dumps(r)+'\n' for r in records))
